```bash
cd /home/vscode/nullness-benchmarks/glide && sed -i '1119,1144d;1118a\ \ \ \ \ \ if (errorRequestCoordinator == null) {
\ \ \ \ \ \ \ \ return mainRequest;
\ \ \ \ \ \ }
\ 
\ \ \ \ \ \ @SuppressWarnings("ConstantConditions")
\ \ \ \ \ \ RequestBuilder<TranscodeType> nonNullErrorBuilder = errorBuilder;
\ 
\ \ \ \ \ \ int errorOverrideWidth = nonNullErrorBuilder.getOverrideWidth();
\ \ \ \ \ \ int errorOverrideHeight = nonNullErrorBuilder.getOverrideHeight();
\ \ \ \ \ \ if (Util.isValidDimensions(overrideWidth, overrideHeight) && !nonNullErrorBuilder.isValidOverride()) {
\ \ \ \ \ \ \ \ errorOverrideWidth = requestOptions.getOverrideWidth();
\ \ \ \ \ \ \ \ errorOverrideHeight = requestOptions.getOverrideHeight();
\ \ \ \ \ \ }
\ 
\ \ \ \ \ \ Request errorRequest =
\ \ \ \ \ \ \ \ \ \ nonNullErrorBuilder.buildRequestRecursive(
\ \ \ \ \ \ \ \ \ \ \ \ \ \ requestLock,
\ \ \ \ \ \ \ \ \ \ \ \ \ \ target,
\ \ \ \ \ \ \ \ \ \ \ \ \ \ targetListener,
\ \ \ \ \ \ \ \ \ \ \ \ \ \ errorRequestCoordinator,
\ \ \ \ \ \ \ \ \ \ \ \ \ \ nonNullErrorBuilder.transitionOptions,
\ \ \ \ \ \ \ \ \ \ \ \ \ \ nonNullErrorBuilder.getPriority(),
\ \ \ \ \ \ \ \ \ \ \ \ \ \ errorOverrideWidth,
\ \ \ \ \ \ \ \ \ \ \ \ \ \ errorOverrideHeight,
\ \ \ \ \ \ \ \ \ \ \ \ \ \ nonNullErrorBuilder,
\ \ \ \ \ \ \ \ \ \ \ \ \ \ callbackExecutor);
\ \ \ \ \ \ errorRequestCoordinator.setRequests(mainRequest, errorRequest);
\ \ \ \ \ \ return errorRequestCoordinator;' library/src/main/java/com/bumptech/glide/RequestBuilder.java && ./gradlew library:compileDebugJavaWithJavac -x test -q > new_build_output.log 2>&1 && (grep -n "DEREFERENCE_NULLABLE" new_build_output.log | head; grep -n "85 errors" new_build_output.log || grep -n "84 errors" new_build_output.log || tail -n 20 new_build_output.log)
```

